#include <omp.h>
#include <vector>
#include <array>
#include <cstddef>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    #pragma omp parallel
    {
        std::array<size_t, 10> local_bins{};
        local_bins.fill(0);

        #pragma omp for nowait
        for (std::size_t i = 0; i < x.size(); ++i) {
            double v = x[i];
            if (v >= 0.0 && v <= 100.0) {
                int idx = static_cast<int>(v / 10.0);
                if (idx == 10) idx = 9; // Include 100 in the last bin [90,100]
                ++local_bins[static_cast<std::size_t>(idx)];
            }
        }

        #pragma omp critical
        {
            for (std::size_t b = 0; b < 10; ++b) {
                bins[b] += local_bins[b];
            }
        }
    }
}
